"""
Wait policies for rollup partition mappers.

A :class:`RollupMapper` gathers many upstream partition keys into one downstream
key. A ``WaitPolicy`` decides, given the set of upstream keys that have arrived
so far (*matched*) and the full set the window expects (*expected*), whether the
downstream Dag run may fire yet — and, importantly, whether it can *ever* fire.

Runtime evaluation lives here on the scheduler side; the Task SDK carries
lightweight authoring-only mirrors in
``airflow.sdk.definitions.partition_mappers.wait_policy``.
"""

from __future__ import annotations

from abc import ABC, abstractmethod
from dataclasses import dataclass
from typing import Any


@dataclass
class PartitionSatisfaction:
    """
    Result of evaluating a :class:`WaitPolicy` against a set of arrived keys.

    ``satisfied`` says the downstream Dag run may fire now. ``unreachable`` says
    the policy can *never* be satisfied for this window (e.g. a fixed threshold
    larger than the window's cardinality); when set, ``unreachable_reason``
    carries a human-readable explanation. The cross-field invariant is enforced
    at construction time so an impossible ``(unreachable, unreachable_reason)``
    combination cannot silently flow through the scheduler.
    """

    satisfied: bool
    unreachable: bool
    unreachable_reason: str | None

    def __post_init__(self) -> None:
        if self.unreachable and self.unreachable_reason is None:
            raise ValueError("unreachable_reason must be set when unreachable is True")
        if not self.unreachable and self.unreachable_reason is not None:
            raise ValueError("unreachable_reason must be None when unreachable is False")


class WaitPolicy(ABC):
    """
    Abstract base class for rollup wait policies.

    Subclasses implement :meth:`is_satisfied` (does the arrived count clear the
    bar?) and :meth:`is_unreachable` (can the bar ever be cleared for a window
    of this size?). :meth:`is_satisfied_by_keys` provides the default bridge
    from key *sets* to those count-based predicates, and is the single entry
    point the scheduler calls.
    """

    @abstractmethod
    def is_satisfied(self, matched: int, expected: int) -> bool:
        """Return whether *matched* arrived keys clear the bar for *expected* window size."""
        raise NotImplementedError

    @abstractmethod
    def is_unreachable(self, expected: int) -> bool:
        """Return whether the policy can never be satisfied given *expected* window size."""
        raise NotImplementedError

    def is_satisfied_by_keys(self, matched: set, expected: set) -> PartitionSatisfaction:
        """
        Evaluate the policy against the arrived and expected key sets.

        Counts only keys that are both arrived and expected (the intersection),
        so stray keys outside the window never count toward satisfaction. If the
        policy is unreachable for this window size the result carries the reason
        instead of a satisfaction verdict.
        """
        expected_count = len(expected)
        if self.is_unreachable(expected_count):
            reason = (
                f"wait policy {self!r} can never be satisfied given the window's "
                f"cardinality {expected_count}"
            )
            return PartitionSatisfaction(satisfied=False, unreachable=True, unreachable_reason=reason)
        matched_count = len(matched & expected)
        satisfied = self.is_satisfied(matched_count, expected_count)
        return PartitionSatisfaction(satisfied=satisfied, unreachable=False, unreachable_reason=None)

    def serialize(self) -> dict[str, Any]:
        """Return the JSON-compatible state of this policy (``Encoding.VAR`` payload)."""
        return {}

    @classmethod
    def deserialize(cls, data: dict[str, Any]) -> WaitPolicy:
        """Reconstruct a policy from the payload produced by :meth:`serialize`."""
        return cls()


class WaitForAll(WaitPolicy):
    """
    Fire only once every expected upstream key has arrived.

    This is the default rollup behaviour: the downstream run is held until the
    window is complete. Stateless — all instances are equal and interchangeable.
    """

    def __repr__(self) -> str:
        return "WaitForAll()"

    def __eq__(self, other: object) -> bool:
        # Compare by class name so the SDK authoring mirror and this scheduler
        # variant (independent hierarchies) round-trip as equal.
        return type(self).__name__ == type(other).__name__

    def __hash__(self) -> int:
        return hash(type(self).__name__)

    def is_satisfied(self, matched: int, expected: int) -> bool:
        return matched == expected

    def is_unreachable(self, expected: int) -> bool:
        return False

    def is_satisfied_by_keys(self, matched: set, expected: set) -> PartitionSatisfaction:
        # Short-circuit: complete exactly when every expected key has arrived.
        return PartitionSatisfaction(
            satisfied=expected.issubset(matched), unreachable=False, unreachable_reason=None
        )


class MinimumCount(WaitPolicy):
    """
    Fire once at least a threshold number of upstream keys have arrived.

    A positive *n* is an absolute threshold: fire when ``matched >= n``. A
    negative *n* is relative to the window size: fire when
    ``matched >= max(0, expected + n)`` (e.g. ``n=-3`` on a 60-key window fires
    at 57, tolerating up to 3 missing keys). ``n=0`` is rejected — it is
    degenerate (an absolute threshold that is always met, or a no-op relative
    offset).
    """

    def __init__(self, n: int) -> None:
        if n == 0:
            raise ValueError("MinimumCount(0) is degenerate; use a positive or negative threshold")
        self.n = n

    def __repr__(self) -> str:
        return f"MinimumCount(n={self.n})"

    def __eq__(self, other: object) -> bool:
        return type(self).__name__ == type(other).__name__ and self.n == getattr(other, "n", None)

    def __hash__(self) -> int:
        return hash((type(self).__name__, self.n))

    def is_satisfied(self, matched: int, expected: int) -> bool:
        if self.n > 0:
            return matched >= self.n
        return matched >= max(0, expected + self.n)

    def is_unreachable(self, expected: int) -> bool:
        # An absolute threshold larger than the window can never be met. A
        # relative threshold shrinks with the window, so it is always reachable.
        return self.n > 0 and self.n > expected

    def serialize(self) -> dict[str, Any]:
        return {"n": self.n}

